      "id": "arxiv:2609.35641v1",
      "title": "Verifiable Visual Rewards Transfer from Synthetic Scenes to Natural Prompts",
      "url": "https://arxiv.org/abs/2609.35641v1",
      "pdfUrl": "https://arxiv.org/pdf/2609.35641v1",
      "source": "arXiv",
