        "id": "arxiv:2609.35695v1",
        "title": "Rethinking Personalized Generation: Test-Time Alignment via Factorized Ranking Models",
        "url": "https://arxiv.org/abs/2609.35695v1",
        "pdfUrl": "https://arxiv.org/pdf/2609.35695v1",
